<?php
require_once '../../config/database_config.php';
require_once '../../includes/session.php';  header('Content-Type: application/json');  class StaffCalendarAPI {  private $pdo;  private $station_id;  private $user_id;  private $user_role;  public function __construct($pdo) {  $this->pdo = $pdo;  $this->station_id = $_SESSION['station_id'] ?? null;  $this->user_id = $_SESSION['user_id'] ?? null;  $this->user_role = $_SESSION['role'] ?? null;  if (!$this->station_id || !$this->user_id) {  http_response_code(401);  echo json_encode(['error' => 'Unauthorized']);  exit;  }  }  public function handleRequest() {  $action = $_GET['action'] ?? '';  switch ($action) {  case 'get_events':  return $this->getEvents();  case 'get_event_types':  return $this->getEventTypes();  case 'get_staff_members':  return $this->getStaffMembers();  case 'get_managers':  return $this->getManagers();  case 'add_event':  return $this->addEvent();  case 'update_event':  return $this->updateEvent();  case 'delete_event':  return $this->deleteEvent();  case 'get_dashboard_data':  return $this->getDashboardData();  case 'get_today_events':  return $this->getTodayEvents();  case 'get_upcoming_events':  return $this->getUpcomingEvents();  default:  http_response_code(400);  return ['error' => 'Invalid action'];  }  }  private function getEvents() {  $month = $_GET['month'] ?? date('Y-m');  $status_filter = $_GET['status'] ?? '';  try {  $query = "  SELECT * FROM staff_calendar_summary  WHERE station_id = :station_id  AND DATE_FORMAT(event_date, '%Y-%m') = :month  ";  $params = [  ':station_id' => $this->station_id,  ':month' => $month  ];  if ($status_filter) {  $query .= " AND status = :status";  $params[':status'] = $status_filter;  }  $query .= " ORDER BY event_date, start_time";  $stmt = $this->pdo->prepare($query);  $stmt->execute($params);  $events = $stmt->fetchAll(PDO::FETCH_ASSOC);  return ['success' => true, 'events' => $events];  } catch (Exception $e) {  return ['success' => false, 'error' => $e->getMessage()];  }  }  private function getEventTypes() {  try {  $stmt = $this->pdo->prepare("  SELECT `user_id`, type_key, type_name, description, icon_class, color_class  FROM staff_event_types  WHERE is_active = TRUE  ORDER BY sort_order  ");  $stmt->execute();  $event_types = $stmt->fetchAll(PDO::FETCH_ASSOC);  return ['success' => true, 'event_types' => $event_types];  } catch (Exception $e) {  return ['success' => false, 'error' => $e->getMessage()];  }  }  private function getStaffMembers() {  try {  $stmt = $this->pdo->prepare("  SELECT u.id, u.first_name, u.last_name, u.email,  COALESCE(scc.color_code, '#007bff') as color_code,  COALESCE(scc.color_name, 'Blue') as color_name  FROM users u  LEFT JOIN staff_color_config scc ON u.id = scc.user_id AND scc.is_active = TRUE  WHERE u.station_id = :station_id  AND u.role IN ('staff', 'cashier', 'pump_attendant')  AND u.account_status = 'Active'  ORDER BY u.first_name, u.last_name  ");  $stmt->execute([':station_id' => $this->station_id]);  $staff = $stmt->fetchAll(PDO::FETCH_ASSOC);  return ['success' => true, 'staff' => $staff];  } catch (Exception $e) {  return ['success' => false, 'error' => $e->getMessage()];  }  }  private function getManagers() {  try {  $stmt = $this->pdo->prepare("  SELECT u.id, u.first_name, u.last_name, u.email,  COALESCE(mcc.color_code, '#dc3545') as color_code,  COALESCE(mcc.color_name, 'Red') as color_name  FROM users u  LEFT JOIN manager_color_config mcc ON u.id = mcc.user_id AND mcc.is_active = TRUE  WHERE u.station_id = :station_id  AND u.role IN ('manager', 'admin')  AND u.account_status = 'Active'  ORDER BY u.first_name, u.last_name  ");  $stmt->execute([':station_id' => $this->station_id]);  $managers = $stmt->fetchAll(PDO::FETCH_ASSOC);  return ['success' => true, 'managers' => $managers];  } catch (Exception $e) {  return ['success' => false, 'error' => $e->getMessage()];  }  }  private function addEvent() {  $data = json_decode(file_get_contents('php://input'), true);  try {  $stmt = $this->pdo->prepare("  INSERT INTO staff_calendar_events  (station_id, event_type_id, staff_encoder_id, manager_assigned_id,  event_date, start_time, end_time, work_description, status, notes)  VALUES  (:station_id, :event_type_id, :staff_encoder_id, :manager_assigned_id,  :event_date, :start_time, :end_time, :work_description, :status, :notes)  ");  $stmt->execute([  ':station_id' => $this->station_id,  ':event_type_id' => $data['event_type_id'],  ':staff_encoder_id' => $data['staff_encoder_id'],  ':manager_assigned_id' => $data['manager_assigned_id'] ?? null,  ':event_date' => $data['event_date'],  ':start_time' => $data['start_time'],  ':end_time' => $data['end_time'],  ':work_description' => $data['work_description'],  ':status' => $data['status'] ?? 'pending',  ':notes' => $data['notes'] ?? null  ]);  $event_id = $this->pdo->lastInsertId();  return ['success' => true, 'event_id' => $event_id, 'message' => 'Event created successfully'];  } catch (Exception $e) {  return ['success' => false, 'error' => $e->getMessage()];  }  }  private function updateEvent() {  $data = json_decode(file_get_contents('php://input'), true);  $event_id = $data['event_id'] ?? 0;  if (!$event_id) {  return ['success' => false, 'error' => 'Event ID required'];  }  try {  // Check if user has permission to update this event  $check_stmt = $this->pdo->prepare("  SELECT staff_encoder_id, manager_assigned_id  FROM staff_calendar_events  WHERE id = :event_id AND station_id = :station_id  ");  $check_stmt->execute([  ':event_id' => $event_id,  ':station_id' => $this->station_id  ]);  $event = $check_stmt->fetch(PDO::FETCH_ASSOC);  if (!$event) {  return ['success' => false, 'error' => 'Event not found'];  }  $stmt = $this->pdo->prepare("  UPDATE staff_calendar_events  SET event_type_id = :event_type_id,  manager_assigned_id = :manager_assigned_id,  event_date = :event_date,  start_time = :start_time,  end_time = :end_time,  work_description = :work_description,  status = :status,  notes = :notes,  updated_at = CURRENT_TIMESTAMP  WHERE id = :event_id AND station_id = :station_id  ");  $stmt->execute([  ':event_id' => $event_id,  ':event_type_id' => $data['event_type_id'],  ':manager_assigned_id' => $data['manager_assigned_id'] ?? null,  ':event_date' => $data['event_date'],  ':start_time' => $data['start_time'],  ':end_time' => $data['end_time'],  ':work_description' => $data['work_description'],  ':status' => $data['status'],  ':notes' => $data['notes'] ?? null,  ':station_id' => $this->station_id  ]);  return ['success' => true, 'message' => 'Event updated successfully'];  } catch (Exception $e) {  return ['success' => false, 'error' => $e->getMessage()];  }  }  private function deleteEvent() {  $event_id = $_GET['event_id'] ?? 0;  if (!$event_id) {  return ['success' => false, 'error' => 'Event ID required'];  }  try {  $stmt = $this->pdo->prepare("  DELETE FROM staff_calendar_events  WHERE id = :event_id AND station_id = :station_id  ");  $stmt->execute([  ':event_id' => $event_id,  ':station_id' => $this->station_id  ]);  return ['success' => true, 'message' => 'Event deleted successfully'];  } catch (Exception $e) {  return ['success' => false, 'error' => $e->getMessage()];  }  }  private function getDashboardData() {  try {  $stmt = $this->pdo->prepare("  SELECT * FROM staff_calendar_dashboard  WHERE station_id = :station_id  ");  $stmt->execute([':station_id' => $this->station_id]);  $dashboard_data = $stmt->fetch(PDO::FETCH_ASSOC);  return ['success' => true, 'dashboard_data' => $dashboard_data];  } catch (Exception $e) {  return ['success' => false, 'error' => $e->getMessage()];  }  }  private function getTodayEvents() {  try {  $stmt = $this->pdo->prepare("  SELECT * FROM staff_calendar_summary  WHERE station_id = :station_id  AND event_date = CURDATE()  ORDER BY start_time  ");  $stmt->execute([':station_id' => $this->station_id]);  $events = $stmt->fetchAll(PDO::FETCH_ASSOC);  return ['success' => true, 'events' => $events];  } catch (Exception $e) {  return ['success' => false, 'error' => $e->getMessage()];  }  }  private function getUpcomingEvents() {  try {  $stmt = $this->pdo->prepare("  SELECT * FROM staff_calendar_summary  WHERE station_id = :station_id  AND event_date BETWEEN CURDATE() AND DATE_ADD(CURDATE(), INTERVAL 3 DAY)  ORDER BY event_date, start_time  ");  $stmt->execute([':station_id' => $this->station_id]);  $events = $stmt->fetchAll(PDO::FETCH_ASSOC);  return ['success' => true, 'events' => $events];  } catch (Exception $e) {  return ['success' => false, 'error' => $e->getMessage()];  }  }
}  // Initialize and handle request
try {  $pdo = new PDO("mysql:host=$host;dbname=$dbname", $username, $password);  $pdo->setAttribute(PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION);  $api = new StaffCalendarAPI($pdo);  echo json_encode($api->handleRequest());
} catch (Exception $e) {  http_response_code(500);  echo json_encode(['error' => 'Database connection failed: ' . $e->getMessage()]);
}
